  PIECE_QUEUE,
  pieceCells,
  renderBoard,
  runScript,
  SCORE_PER_LINE,
  WIDTH,
  type Command,
  type GameState,
} from './tetris.js';

/**
 * SCRIPT DESIGN — clearing exactly ONE line with the fixed queue
 * [I, O, T, I, S, Z, J, L, I, O] (only the first four pieces are used).
 *
 * Columns are numbered 0..9 left-to-right; rows 0 (top) .. 19 (floor).
 * Pieces spawn top-center: x=3 for width-3 boxes and the I, x=4 for the O.
 *
 * Piece 1 — I (flat):
 *   spawn: box x=3, cells on box row 1 -> cols 3..6.
 *   'left' x3          -> cols 0..3
 *   'hardDrop'         -> locks at row 19, cols 0..3
 *
 * Piece 2 — O:
 *   spawn: box x=4     -> cols 4..5
 *   'hardDrop'         -> locks rows 18-19, cols 4..5
 *
 * Piece 3 — T (flat):
 *   spawn orientation `.X./XXX/...`, box x=3, filled cells on box rows 0-1.
 *   'right' x3         -> box x=6, bottom bar covers cols 6..8
 *   'hardDrop'         -> locks with bar on row 19 (cols 6..8) and its nub at (row18, col7)
 *
 *   Stack now:
 *     row 19: cols 0..8 = "#########."
 *     row 18: cols 4,5 (O) and 7 (T nub) = "....##.#.."
 *
 * Piece 4 — I (vertical), the kill shot down column 9:
 *   'rotate'           -> nudge-free CW in the 4x4 box; vertical I occupies col x+2 = 5
 *   'right' x4         -> x: 3->7, occupied column walks 5->9 (cells stay in-bounds)
 *   'hardDrop'         -> locks rows 16..19 in col 9
 *
 *   Row 19 is now FULL (cols 0..9) -> cleared. Rows above shift down by one:
 *     new row 19 = old row 18 = "....##.#.."
 *     new row 18 = old row 17 = ".........#"
 *     new row 17 = old row 16 = ".........#"
 *
 * Result: linesCleared === 1, score === 100.
 */

const SCRIPT: Command[] = [
  // Piece 1: I flat against the left wall
  'left', 'left', 'left', 'hardDrop',
  // Piece 2: O right next to it
  'hardDrop',
  // Piece 3: T flat, bar covering cols 6..8
  'right', 'right', 'right', 'hardDrop',
  // Piece 4: I rotated vertical, dropped down column 9 -> line clear
  'rotate', 'right', 'right', 'right', 'right', 'hardDrop',
];

/** Property check: a state must never have cells outside the well,
 *  and the active piece must never overlap the stack or leave the well. */
function assertInvariants(state: GameState): void {
  expect(state.board).toHaveLength(HEIGHT);
  for (const row of state.board) {
    expect(row).toHaveLength(WIDTH);
    for (const cell of row) expect(typeof cell).toBe('boolean');
  }
  if (state.active) {
    const occupiedByPiece = new Set<string>();
    for (const [x, y] of pieceCells(state.active)) {
      // never outside the well
      expect(x).toBeGreaterThanOrEqual(0);
      expect(x).toBeLessThan(WIDTH);
      expect(y).toBeGreaterThanOrEqual(0);
      expect(y).toBeLessThan(HEIGHT);
      // never overlapping the locked stack
      expect(state.board[y][x]).toBe(false);
      // never self-overlapping
      const key = `${x},${y}`;
      expect(occupiedByPiece.has(key)).toBe(false);
      occupiedByPiece.add(key);
    }
  }
}

describe('headless tetris — scripted line clear', () => {
  it('clears exactly 1 line, scores 100, ends in the exact expected ASCII stack', () => {
    const snapshots = runScript(createGame(), SCRIPT);

    // initial state + one snapshot per command
    expect(snapshots).toHaveLength(SCRIPT.length + 1);

    // ---- property check EVERY intermediate state ----
    for (const s of snapshots) assertInvariants(s);

    // score must be monotonically non-decreasing across the script
    for (let i = 1; i < snapshots.length; i++) {
      expect(snapshots[i]!.score).toBeGreaterThanOrEqual(snapshots[i - 1]!.score);
    }

    // intermediate checkpoints along the trace
    const afterI1 = snapshots[4]!; // after first hardDrop
    expect(renderBoard(afterI1)[19]).toBe('####......');
    const afterO = snapshots[5]!;
    expect(renderBoard(afterO)[19]).toBe('######....');
    expect(renderBoard(afterO)[18]).toBe('....##....');
    const afterT = snapshots[9]!;
    expect(renderBoard(afterT)[19]).toBe('#########.');
    expect(renderBoard(afterT)[18]).toBe('....##.#..');

    const final = snapshots[snapshots.length - 1]!;

    // exact rows-cleared count
    expect(final.linesCleared).toBe(1);

    // exact score: 100 per line
    expect(SCORE_PER_LINE).toBe(100);
    expect(final.score).toBe(100);

    // exact resulting stack as ASCII (rows 0..19)
    const emptyRow = '.'.repeat(WIDTH);
    expect(renderBoard(final)).toEqual([
      ...Array.from({ length: 17 }, () => emptyRow), // rows 0..16
      '.........#', // row 17 (was old row 16)
      '.........#', // row 18 (was old row 17)
      '....##.#..', // row 19 (was old row 18: O at 4-5, T nub at 7)
    ]);

    // queue bookkeeping: 4 of the 10 fixed pieces consumed, S spawned next
    expect(final.queue).toEqual(['S', 'Z', 'J', 'L', 'I', 'O']);
    expect(final.active?.id).toBe('S');
    expect(final.over).toBe(false);
  });

  it('the fixed queue is deterministic (no RNG)', () => {
    expect(PIECE_QUEUE).toEqual(['I', 'O', 'T', 'I', 'S', 'Z', 'J', 'L', 'I', 'O']);
    const a = createGame();
    const b = createGame();
    expect(a).toEqual(b);
    for (const cmd of SCRIPT) {
      a.board; // touch to ensure no lazy weirdness
      b.board;
      expect(applyCommand(a, cmd)).toEqual(applyCommand(b, cmd));
    }
  });

  it('nudge-free rotation rejects illegal rotations as no-ops', () => {
    // Flat I hugging the left wall cannot rotate (vertical form would need col -2... 
    // actually it rotates into its own box; use a wall case that provably collides:
    // an I flat on the floor at x=6 rotating would put cells out of the well? No --
    // simplest true no-op: rotate the final S spawn while it overlaps nothing? It's legal.
    // Use: drop a flat I to the floor, then fill around so rotation collides via stack:
    let s = createGame();
    s = applyCommand(s, 'hardDrop'); // I flat at row 19, cols 3..6
    // Spawn next piece (O) sits at top; irrelevant. Instead verify: rotating a flat,
    // floor-locked-shaped piece is impossible because active changed -- so test the
    // documented rule directly: vertical I in column 9 (box x=7) cannot move right
    // further (cell would leave the well) and rotation near a wall is rejected.
    s = applyCommand(s, 'rotate'); // now vertical I at top, occupied col 5
    s = applyCommand(s, 'right'); // col 6
    s = applyCommand(s, 'right'); // col 7
    s = applyCommand(s, 'right'); // col 8
    s = applyCommand(s, 'right'); // col 9 — rightmost legal spot
    assertInvariants(s);
    const before = s;
    const afterFailedRight = applyCommand(s, 'right'); // would push cells out of the well
    expect(afterFailedRight.active!.x).toBe(before.active!.x); // rejected, unchanged
    assertInvariants(afterFailedRight);
    const afterRotateAtWall = applyCommand(afterFailedRight, 'rotate'); // horizontal I from col-9 box would stick out right
    // rot 0->1 was already done earlier; from rot 1 back to rot 2 (horizontal) at box x=7
    // puts cells at cols 7..10 -> out of bounds -> silent no-op.
    expect(afterRotateAtWall.active!.rot).toBe(afterFailedRight.active!.rot);
    assertInvariants(afterRotateAtWall);
  });
});
