it('nudge-free rules: moves and rotations that would leave the well are silent no-ops', () => {
  let s = createGame();
  s = applyCommand(s, 'rotate'); // vertical I at top; occupied column = box x + 2 = 5
  s = applyCommand(s, 'right'); // col 6
  s = applyCommand(s, 'right'); // col 7
  s = applyCommand(s, 'right'); // col 8
  s = applyCommand(s, 'right'); // col 9 — rightmost legal spot
  assertInvariants(s);

  // moving right again would push cells out of the well -> rejected
  const afterFailedRight = applyCommand(s, 'right');
  expect(afterFailedRight.active!.x).toBe(s.active!.x);
  assertInvariants(afterFailedRight);

  // rotating rot=1 (vertical) -> rot=2 (horizontal) from box x=7 puts cells in
  // cols 7..10 -> out of bounds -> nudge-free rotation rejects it as a no-op
  const afterRotateAtWall = applyCommand(afterFailedRight, 'rotate');
  expect(afterRotateAtWall.active!.rot).toBe(afterFailedRight.active!.rot);
  assertInvariants(afterRotateAtWall);
});

